const routineMethods={nist_clear:'NIST Clear',nist_purge:'NIST Purge',sanitize_block:'nwipe Block Erase',sanitize_crypto:'nwipe Crypto Erase',sanitize_overwrite:'nwipe Sanitize Overwrite',zero:'Fill with zeros',one:'Fill with ones',prng:'PRNG stream',ops2:'RCMP TSSIT OPS-II',dodshort:'DoD 5220.22-M (short)',dod522022m:'DoD 5220.22-M (full)',gutmann:'Gutmann',is5enh:'HMG IS5 Enhanced',bruce7:'Schneier (7 passes)',bmb:'BMB21-2019',verify_zero:'Verify zeros (read only)',verify_one:'Verify ones (read only)'};
