function routineCapability(method){const found=routineData?.erase_methods?.find(c=>c.id===method);if(found)return found;if(['nist_clear','nist_purge','sanitize_block','sanitize_crypto','sanitize_overwrite'].includes(method))return {engine:'nwipe',verification:['all'],rounds:false,final_blank:false,prng:false,unfreeze:false,pattern:false,invert:false,crypto:method==='sanitize_crypto',readback:false};const verify=method.startsWith('verify_');return {engine:'nwipe',verification:verify||method==='is5enh'?['all']:['all','last','off'],rounds:!verify,final_blank:!['ops2','verify_zero','verify_one'].includes(method),prng:!['zero','one','verify_zero','verify_one'].includes(method),unfreeze:false,pattern:false,invert:false,crypto:false,readback:false};}
function normalizeRoutineWipe(s){const c=routineCapability(s.method);if(!c.verification.includes(s.verification))s.verification=c.verification[0];if(!c.rounds)s.rounds=1;if(!c.final_blank)s.final_blank=false;if(!c.prng)s.prng='auto';if(!c.unfreeze)s.unfreeze=false;if(!c.readback)s.readback='none';if(!c.pattern)s.overwrite_pattern=0;if(!c.invert)s.invert_pattern=false;if(!c.crypto){s.crypto_approved=false;s.crypto_assurance='';}if(s.method==='nist_purge'&&typeof s.prng_followup!=='boolean')s.prng_followup=true;}
