function routineAutoPositions(){const edges=routineEdges(),placed=new Map();function visit(id,depth,lane,trail=new Set()){if(trail.has(id))return;const old=placed.get(id);if(old&&old.depth>=depth&&old.lane<=lane)return;placed.set(id,{depth:Math.max(old?.depth||0,depth),lane:Math.min(old?.lane??lane,lane)});for(const e of edges.filter(e=>e.source===id))visit(e.target,depth+1,lane+(e.outcome==='failure'?1:0),new Set([...trail,id]));}visit(routineDraft.steps[0].id,0,0);return new Map(routineDraft.steps.map((s,i)=>{const p=placed.get(s.id);return [s.id,{x:40+(p?.depth??i)*290,y:70+(p?.lane??2)*210}];}));}
