function zoomRoutineGraph(value,clientX=null,clientY=null){const flow=$('routine-flow'),rect=flow.getBoundingClientRect(),x=clientX===null?flow.clientWidth/2:clientX-rect.left,y=clientY===null?flow.clientHeight/2:clientY-rect.top,pointX=(flow.scrollLeft+x)/routineZoom,pointY=(flow.scrollTop+y)/routineZoom;routineZoom=Math.max(.25,Math.min(2,value));renderRoutineFlow();flow.scrollLeft=Math.max(0,pointX*routineZoom-x);flow.scrollTop=Math.max(0,pointY*routineZoom-y);}
