function connectRoutine(source,target,outcome){if(source===target||routineDraft.steps.find(s=>s.id===target)?.kind==='boot')return;materializeRoutineEdges();routineDraft.connections=routineDraft.connections.filter(e=>e.source!==source||e.outcome!==outcome);routineDraft.connections.push({source,target,outcome});routineConnectionStart=null;routineDirty=true;renderRoutineFlow();renderRoutineStep();routineEditorStatus();}
function arrangeRoutine(){if(!routineDraft)return;const positions=routineAutoPositions();for(const s of routineDraft.steps)Object.assign(s,positions.get(s.id));routineDirty=true;renderRoutineFlow();routineEditorStatus();}

function newRoutineStep(kind){return {id:kind+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),kind,profile_id:null,method:kind==='erase'?'nist_clear':'zero',fallback_method:null,verification:'all',rounds:1,final_blank:kind!=='erase',prng:'auto',io_mode:'auto',direction:'forward',sync_blocks:null,retry_io_errors:true,abort_on_block_errors:true,unfreeze:false,crypto_approved:false,crypto_assurance:'',prng_followup:true,readback:'none',readback_pattern:'readable',overwrite_pattern:0,invert_pattern:false,allow_usb:false,target_policy:kind==='erase'?'all-internal':kind==='windows'?'auto-unless-multiple':'single-internal',target_identity:null,note:'',ipxe_path:'',start_delay_seconds:5,verify_image:true,finish_options:kind==='windows'?defaultRoutineFinish():null,x:null,y:null};}
function routineOptions(list,value,empty='Choose…'){return '<option value="">'+esc(empty)+'</option>'+list.map(r=>'<option value="'+esc(r.id)+'"'+(r.id===value?' selected':'')+'>'+esc(r.name)+'</option>').join('');}
