 const c=routineCapability(s.method),disabled=flag=>flag?'':' disabled',select=(name,choices,value,enabled=true)=>'<label>'+name+'<select data-routine-field="'+choices.field+'"'+disabled(enabled)+'>'+Object.entries(choices.values).map(([k,v])=>'<option value="'+esc(k)+'"'+(k===value?' selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>';
