function openRoutine(id){if(routineDirty&&id!==routineEditingId){message('Save or discard the current draft first.',true);return;}const r=routineData?.routines.find(r=>r.id===id);if(!r)return;routineEditingId=id;routineGeneration=r.generation;routineDraft=JSON.parse(JSON.stringify(r.draft));routineDirty=false;routineSelectedStep=routineDraft.steps[1].id;$('routine-editor').hidden=false;$('routine-name').value=routineDraft.name;$('routine-version').textContent=r.published_version?'Published v'+r.published_version:'Draft';renderRoutineList();renderRoutineFlow();renderRoutineStep();routineEditorStatus();}
function addRoutineStep(kind,index=null,position=null){if(!routineDraft)return;if(['windows','inventory'].includes(kind)&&routineDraft.steps.some(s=>s.kind===kind)){message('This routine already has that step.',true);return;}materializeRoutineEdges();const s=newRoutineStep(kind);index=index??routineDraft.steps.length-1;index=Math.max(1,Math.min(routineDraft.steps.length-1,index));if(position){s.x=position.x;s.y=position.y;}const target=routineDraft.steps[index];if(kind==='ipxe'||(kind==='erase'&&routineDraft.steps.some(n=>n.kind==='erase'))){routineDraft.connections.push({source:s.id,target:routineDraft.steps.at(-1).id,outcome:'success'});}else{for(const edge of routineDraft.connections)if(edge.target===target.id&&edge.outcome==='success')edge.target=s.id;routineDraft.connections.push({source:s.id,target:target.id,outcome:'success'});}routineDraft.steps.splice(index,0,s);routineSelectedStep=s.id;routineDirty=true;renderRoutineFlow();renderRoutineStep();routineEditorStatus();}
function moveRoutineStep(from,to){if(!routineDraft||from<1||from>=routineDraft.steps.length-1)return;to=Math.max(1,Math.min(routineDraft.steps.length-2,to));const [s]=routineDraft.steps.splice(from,1);routineDraft.steps.splice(to,0,s);routineDraft.connections=[];routineDraft.graph=false;routineDirty=true;renderRoutineFlow();routineEditorStatus();}
function renderRoutineRuns(){const mode=$('routine-run-filter').value||'active';const runs=sortDevices(routineData?.runs||[]).filter(r=>mode==='all'||(mode==='attention'?r.needs_attention:!['complete','failed','cancelled'].includes(r.stage)));$('routine-runs').innerHTML=runs.length?table(['Routine / client','Step','Status','Evidence','Controls'],runs.map(r=>['<button class="client-name" data-routine-run="'+esc(r.id)+'">'+esc(r.name)+'</button><small>'+esc(deviceLabel(r))+' · v'+r.version+'</small>',esc(routineKinds[r.steps[r.step]?.kind]||r.stage),routineStatusBadge(r)+eraseProgressHtml(r)+(r.error?'<small class="error">'+esc(r.error)+'</small>':''),(r.certificate_url?'<a href="'+esc(r.certificate_url)+'">Certificate PDF</a> ':'')+'<button class="secondary compact" data-routine-report="'+esc(r.report_id||'routine:'+r.id)+'">Report</button>',(r.can_continue?'<button class="primary compact" data-routine-action="continue" data-run="'+esc(r.id)+'" data-step="'+r.step+'">Continue</button> ':'')+(r.can_cancel?'<button class="secondary compact" data-routine-action="cancel" data-run="'+esc(r.id)+'" data-step="'+r.step+'" aria-label="Cancel job">Cancel job</button>':'')])):'<p class="muted">No matching runs.</p>';}
async function refreshRoutines(){const user=webSession?.user.id;const [data,profiles,caps]=await Promise.all([api('/routines'),api('/profiles'),api('/capabilities')]);if(tab!=='routines'||webSession?.user.id!==user)return;routineData=data;routineProfiles=profiles;renderRoutineList();renderRoutineRuns();const opts=routineOptions(routinePublished(),data.settings.default_id,'No default routine');if(document.activeElement!==$('routine-default'))$('routine-default').innerHTML=opts;$('routine-enabled').checked=data.settings.enabled;$('routine-migrate').hidden=data.routines.length>0;if(document.activeElement!==$('routine-assignment-choice'))$('routine-assignment-choice').innerHTML=routineOptions(routinePublished(),$('routine-assignment-choice').value,'Use website default');$('routine-assignments').innerHTML=data.assignments.length?table(['MAC','Routine','Controls'],data.assignments.map(a=>[esc(a.mac),esc(routinePublished().find(r=>r.id===a.routine_id)?.name||a.routine_id),'<button class="secondary compact" data-routine-unassign="'+esc(a.mac)+'" aria-label="Remove assignment">×</button>'])):'<p class="muted">Clients use the website default.</p>';const cap=caps[0];$('routine-capability-status').textContent=cap?.status==='installed'?'Built-in ShredOS ready':cap?.detail||'Preparing built-in ShredOS';if(routineDraft&&!routineDirty&&!document.activeElement?.closest('#routine-step-settings'))renderRoutineStep();$('routine-enable').hidden=data.settings.enabled;}
async function showRoutineRun(id,record=true){const generation=portalNavigationGeneration,user=webSession?.user.id,r=await api('/routine-runs/'+id);if(!webSession||webSession.user.id!==user||generation!==portalNavigationGeneration)return;routineRunId=id;$('details-title').textContent='Routine job · '+deviceLabel(r);const actions=routineJobActions(r);$('detail-actions').innerHTML=actions;$('job-summary').innerHTML=(r.needs_attention?'<p>'+routineStatusBadge(r)+'</p>':'')+(r.device?deviceSpecs(r.device,r):'')+stats([['Routine',r.name+' · v'+r.version],['Current step',r.step_label||routineKinds[r.steps[r.step]?.kind]],['Status',routineRunStatus(r)],['Model',[r.manufacturer,r.model].filter(Boolean).join(' ')||'Not identified'],['System serial',r.system_serial||'Not reported'],['MAC',r.mac],['Disk',r.target||'Not selected'],['Capacity',r.size?bytes(r.size):'Not reported'],['Last activity',clientMinutesAgo(r.last_activity||r.updated)]])+'<div id="routine-erase-progress">'+eraseProgressHtml(r)+'</div>'+assetReports(r.device?.attachments||r.attachments||[])+(r.error?'<p class="error">'+esc(r.error)+'</p>':'')+'<div class="routine-run-steps">'+r.steps.map((s,i)=>'<span class="badge '+(i===r.step?'current':'')+'">'+esc(routineKinds[s.kind])+'</span>').join('<span>→</span>')+'</div>'+(r.inventory?stats([['CPU',r.inventory.cpu||'Not reported'],['RAM',r.inventory.memory_bytes?bytes(r.inventory.memory_bytes):'Not reported']]):'')+'<h3>Routine timeline</h3><ol class="job-events">'+r.events.map(e=>'<li><strong>'+esc(e.stage)+'</strong> <small>'+esc(dateText(e.created))+'</small><div>'+esc(e.detail)+'</div></li>').join('')+'</ol>';$('detail-text').textContent=JSON.stringify(r,null,2);openPortalDialog('details');if(record)rememberPortalNavigation({kind:'routine',id});}

async function saveRoutine(){if(!routineDraft||routineBusy)return;const crypto=routineDraft.steps.find(s=>s.kind==='erase'&&s.method==='sanitize_crypto'&&(!s.crypto_approved||(s.crypto_assurance||'').trim().length<20));if(crypto){routineSelectedStep=crypto.id;renderRoutineFlow();renderRoutineStep();message('Crypto Erase needs approval and at least 20 characters of encryption / key assurance.',true);return;}routineBusy=true;routineEditorStatus();try{routineDraft.name=$('routine-name').value.trim();const r=await api('/routines'+(routineEditingId?'/'+routineEditingId:''),{method:routineEditingId?'PUT':'POST',body:JSON.stringify(routineEditingId?{spec:routineDraft,expected_generation:routineGeneration}:routineDraft)});routineEditingId=r.id;routineGeneration=r.generation;routineDirty=false;await refreshRoutines();openRoutine(r.id);message('Draft saved.');}catch(e){message(e.message,true);}finally{routineBusy=false;routineEditorStatus();}}
$('routine-new').addEventListener('click',()=>{if(routineDirty){message('Save or discard the current draft first.',true);return;}routineEditingId=null;routineGeneration=0;routineDraft={name:'New routine',steps:[newRoutineStep('boot'),newRoutineStep('windows'),newRoutineStep('finish')]};routineSelectedStep=routineDraft.steps[1].id;routineDirty=true;$('routine-editor').hidden=false;$('routine-name').value=routineDraft.name;$('routine-version').textContent='Draft';renderRoutineFlow();renderRoutineStep();routineEditorStatus();});
$('routine-list').addEventListener('click',e=>{const b=e.target.closest('[data-routine-id]');if(b)openRoutine(b.dataset.routineId);});$('routine-search').addEventListener('input',renderRoutineList);
$('routine-name').addEventListener('input',()=>{if(routineDraft){routineDraft.name=$('routine-name').value;routineDirty=true;routineEditorStatus();}});
$('routine-save').addEventListener('click',saveRoutine);
$('routine-publish').addEventListener('click',async()=>{if(routineBusy||routineDirty)return;routineBusy=true;routineEditorStatus();try{await api('/routines/'+routineEditingId+'/publish',{method:'POST',body:JSON.stringify({expected_generation:routineGeneration})});await refreshRoutines();openRoutine(routineEditingId);message('Published for new boots. Active runs keep their version.');}catch(e){message(e.message,true);}finally{routineBusy=false;routineEditorStatus();}});
$('routine-discard').addEventListener('click',()=>{routineDirty=false;if(routineEditingId)openRoutine(routineEditingId);else{routineDraft=null;$('routine-editor').hidden=true;}routineEditorStatus();});
$('routine-palette').addEventListener('click',e=>{const b=e.target.closest('[data-routine-add]');if(b)addRoutineStep(b.dataset.routineAdd);});
$('routine-flow').addEventListener('click',e=>{if(routineSuppressClick||routinePointer?.moved)return;const edge=e.target.closest('[data-routine-edge]');if(edge){materializeRoutineEdges();routineDraft.connections.splice(Number(edge.dataset.routineEdge),1);routineDirty=true;renderRoutineFlow();renderRoutineStep();routineEditorStatus();return;}const b=e.target.closest('button');if(!b)return;if(b.dataset.routineOutput){routineConnectionStart={source:b.dataset.routineOutput,outcome:b.dataset.outcome};renderRoutineFlow();return;}if(b.dataset.routineInput&&routineConnectionStart){connectRoutine(routineConnectionStart.source,b.dataset.routineInput,routineConnectionStart.outcome);return;}if(b.dataset.routineStep){routineSelectedStep=b.dataset.routineStep;renderRoutineFlow();renderRoutineStep();}if(b.dataset.routineRemove){materializeRoutineEdges();const id=b.dataset.routineRemove,incoming=routineDraft.connections.filter(e=>e.target===id),next=routineDraft.connections.find(e=>e.source===id&&e.outcome==='success');routineDraft.connections=routineDraft.connections.filter(e=>e.source!==id&&e.target!==id);if(next)routineDraft.connections.push(...incoming.map(e=>({...e,target:next.target})));routineDraft.steps=routineDraft.steps.filter(s=>s.id!==id);routineSelectedStep=routineDraft.steps[1]?.id;routineDirty=true;renderRoutineFlow();renderRoutineStep();routineEditorStatus();}});
$('routine-step-settings').addEventListener('change',e=>{const s=routineDraft?.steps.find(s=>s.id===routineSelectedStep);if(!s)return;if(e.target.dataset.routineFinishEnable!==undefined){s.finish_options=e.target.checked?defaultRoutineFinish():null;routineDirty=true;renderRoutineStep();routineEditorStatus();return;}const finishField=e.target.dataset.routineFinish;if(finishField&&s.finish_options){s.finish_options[finishField]=e.target.type==='checkbox'?e.target.checked:e.target.value;routineDirty=true;if(finishField==='setup_mode')renderRoutineStep();routineEditorStatus();return;}const branch=e.target.dataset.routineBranch;if(branch){if(e.target.value)connectRoutine(s.id,e.target.value,branch);else{materializeRoutineEdges();routineDraft.connections=routineDraft.connections.filter(edge=>edge.source!==s.id||edge.outcome!==branch);routineDirty=true;renderRoutineFlow();routineEditorStatus();}return;}const field=e.target.dataset.routineField;if(!field||e.target.disabled)return;s[field]=e.target.type==='checkbox'?e.target.checked:['rounds','overwrite_pattern','sync_blocks','start_delay_seconds'].includes(field)?(e.target.value===''?null:Number(e.target.value)):e.target.value||null;if(field==='method')normalizeRoutineWipe(s);routineDirty=true;renderRoutineFlow();if(['target_policy','method','readback','prng_followup'].includes(field))renderRoutineStep();routineEditorStatus();});
for(const id of ['routine-palette','routine-flow'])$(id).addEventListener('dragstart',e=>{const p=e.target.closest('[data-routine-add]'),port=e.target.closest('[data-routine-output]');if(p)e.dataTransfer.setData('text/plain','add:'+p.dataset.routineAdd);else if(port)e.dataTransfer.setData('text/plain','connect:'+port.dataset.routineOutput+':'+port.dataset.outcome);});
$('routine-flow').addEventListener('dragover',e=>e.preventDefault());$('routine-flow').addEventListener('drop',e=>{e.preventDefault();const [action,value,outcome]=e.dataTransfer.getData('text/plain').split(':'),node=e.target.closest('[data-node-id]');if(action==='connect'&&node)connectRoutine(value,node.dataset.nodeId,outcome);if(action==='add'&&routineKinds[value]){const rect=$('routine-flow').getBoundingClientRect();addRoutineStep(value,null,{x:Math.max(20,(e.clientX-rect.left+$('routine-flow').scrollLeft)/routineZoom-120),y:Math.max(20,(e.clientY-rect.top+$('routine-flow').scrollTop)/routineZoom-30)});}});
$('routine-flow').addEventListener('pointerdown',e=>{if(!routineDraft||![0,1].includes(e.button))return;const title=e.target.closest('[data-routine-step]'),flow=$('routine-flow');if(title&&e.button===0){const s=routineDraft.steps.find(s=>s.id===title.dataset.routineStep),p=routineNodePosition(s,routineDraft.steps.indexOf(s));routinePointer={id:s.id,startX:e.clientX,startY:e.clientY,x:p.x,y:p.y,moved:false};}else if(e.button===1||!e.target.closest('.routine-node,[data-routine-edge]')){e.preventDefault();routinePointer={pan:true,startX:e.clientX,startY:e.clientY,x:flow.scrollLeft,y:flow.scrollTop,moved:false};flow.classList.add('panning');}if(routinePointer?.pan)flow.setPointerCapture?.(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!routinePointer)return;const dx=e.clientX-routinePointer.startX,dy=e.clientY-routinePointer.startY;if(Math.abs(dx)+Math.abs(dy)<5)return;routinePointer.moved=true;if(routinePointer.pan){$('routine-flow').scrollLeft=routinePointer.x-dx;$('routine-flow').scrollTop=routinePointer.y-dy;return;}const s=routineDraft.steps.find(s=>s.id===routinePointer.id);s.x=Math.max(0,Math.min(12000,routinePointer.x+dx/routineZoom));s.y=Math.max(0,Math.min(12000,routinePointer.y+dy/routineZoom));routineDirty=true;$('routine-flow').setPointerCapture?.(e.pointerId);renderRoutineFlow();routineEditorStatus();});
function releaseRoutinePointer(){if(!routinePointer)return;const {moved,id,pan}=routinePointer;routinePointer=null;$('routine-flow').classList.remove('panning');routineSuppressClick=moved;setTimeout(()=>{routineSuppressClick=false;},0);if(moved&&!pan){routineSelectedStep=id;renderRoutineStep();}}
document.addEventListener('pointerup',releaseRoutinePointer);document.addEventListener('pointercancel',releaseRoutinePointer);
$('routine-flow').addEventListener('wheel',e=>{if(!routineDraft||!(e.ctrlKey||e.metaKey))return;e.preventDefault();zoomRoutineGraph(routineZoom*Math.exp(-e.deltaY*.002),e.clientX,e.clientY);},{passive:false});
