async function refreshRoutineMenu(){const user=webSession?.user.id;const [data]=await Promise.all([api('/routine-menu'),loadBootBackground()]);if(tab!=='ipxe'||webSession?.user.id!==user)return;if(routineMenu&&(routineMenuDirty||document.activeElement?.closest('#routine-menu-form')))return;routineMenu=data;$('routine-menu-title').value=data.spec.title;$('routine-menu-start').value=data.spec.start_label;$('routine-menu-other').value=data.spec.other_label;for(const k of ['theme','text_size'])$('routine-menu-'+k).value=data.spec[k];for(const k of ['graphics','show_banner'])$('routine-menu-'+k).checked=data.spec[k];for(const k of ['next','shutdown','firmware'])$('routine-menu-'+k).checked=data.spec[k==='next'?'next_boot':k];$('routine-menu-preview').textContent=data.preview;}
