function clearRoutineSession(){selectedRoutineJobs.clear();routineJobRows=[];routineJobsPage=1;routineJobBusy=false;routineMenuDirty=false;routineData=null;routineProfiles=[];routineDraft=null;routineEditingId=null;routineDirty=false;routineMenu=null;routineRunId=null;routineBusy=false;$('routine-editor').hidden=true;$('routine-run-detail').hidden=true;}
