let routineJobsPage=1,routineJobsPages=1,routineJobsView='active',routineJobsSearch='',routineJobRows=[],routineJobBusy=false;
const selectedRoutineJobs=new Map();
function routineRunStatus(r){if(['complete','failed','cancelled'].includes(r.stage))return stageName(r.stage);if(r.needs_attention){if(r.erase_stage==='erasing')return 'Needs attention · wipe updates stopped';if(r.client_stage==='waiting-for-input')return 'Needs attention · select Windows disk';if(r.erase_stage==='operation-pending')return 'Needs attention · controller outcome pending';if(r.stage==='checkpoint'||r.stage==='custom-boot')return 'Needs attention · technician checkpoint';return stageName(r.effective_stage||r.client_stage||'needs-operator');}return r.client_stage&&r.stage==='windows-running'?stageName(r.client_stage):r.erase_stage&&r.stage==='erase-running'?({queued:'Waiting for ShredOS',claimed:'Disk identified',erasing:'Erasing and verifying','operation-pending':'Controller outcome pending · inspect locally'})[r.erase_stage]||r.erase_stage:r.status_label||({'discovering':'Identifying PC','windows-boot':'Starting Windows install','checkpoint':'Technician checkpoint','custom-boot':'Custom iPXE','complete':'Complete','cancelled':'Cancelled','failed':'Failed'})[r.stage]||r.stage;}
function routineJobActions(r){return '<div class="client-actions">'+(r.can_remove?'<button class="secondary compact" data-routine-remove-job="'+esc(r.id)+'">Remove job</button>':'')+(r.can_continue?'<button class="primary compact" data-routine-action="continue" data-run="'+esc(r.id)+'" data-step="'+r.step+'">Continue</button>':'')+(r.can_cancel?'<button class="secondary compact" data-routine-action="cancel" data-run="'+esc(r.id)+'" data-step="'+r.step+'" aria-label="Cancel job">Cancel job</button>':['erasing','operation-pending'].includes(r.erase_stage)?'<small>Inspect erasure locally</small>':'')+(r.client_id?'<button class="secondary compact" data-routine-client="'+esc(r.client_id)+'">Windows controls</button>':'')+'<button class="secondary compact" data-routine-report="'+esc(r.report_id||'routine:'+r.id)+'">Report</button>'+(r.certificate_url?'<a class="secondary compact" href="'+esc(r.certificate_url)+'" download>Certificate</a>':'')+'</div>';}
function routineJobQuery(){return '?'+new URLSearchParams({view:routineJobsView,search:routineJobsSearch,page:String(routineJobsPage)});}
async function refreshRoutineJobs(){const query=routineJobQuery(),user=webSession?.user.id,data=await api('/routine-jobs'+query);if(tab!=='jobs'||webSession?.user.id!==user||query!==routineJobQuery())return;renderRoutineJobs(data);}
function renderRoutineJobs(data){routineJobRows=sortDevices(data.runs||[]);routineJobsPage=data.page||1;routineJobsPages=data.pages||1;for(const r of routineJobRows)if(selectedRoutineJobs.has(r.id))selectedRoutineJobs.set(r.id,r);$('routine-job-count').textContent=(data.total||0)+' jobs';$('routine-job-page').textContent='Page '+routineJobsPage+' of '+routineJobsPages;$('routine-job-prev').disabled=routineJobsPage<=1;$('routine-job-next').disabled=routineJobsPage>=routineJobsPages;$('routine-jobs-table').innerHTML=routineJobRows.length?table(['Select','Client','Routine','Step','Status','Last activity','Controls'],routineJobRows.map(r=>['<input type="checkbox" data-routine-job-select="'+esc(r.id)+'" aria-label="Select '+esc(deviceLabel(r))+'"'+(selectedRoutineJobs.has(r.id)?' checked':'')+'>','<button class="client-name" data-routine-run="'+esc(r.id)+'">'+esc(deviceLabel(r))+'</button><small>'+esc([r.manufacturer,r.model].filter(Boolean).join(' · '))+'</small>',esc(r.name)+'<small>v'+r.version+'</small>',esc(r.step_label||routineKinds[r.steps[r.step]?.kind])+'<small>'+(r.step+1)+' / '+r.steps.length+'</small>', routineStatusBadge(r)+eraseProgressHtml(r)+(r.install_percent!==null&&r.install_percent!==undefined?'<small>'+r.install_percent+'% installed</small>':'')+(r.error?'<small class="error">'+esc(r.error)+'</small>':''),esc(clientMinutesAgo(r.last_activity||r.updated)),routineJobActions(r)])):empty('No matching routine jobs');updateRoutineJobSelection();}
function updateRoutineJobSelection(){const visible=new Set(routineJobRows.map(r=>r.id)),hidden=[...selectedRoutineJobs.keys()].filter(id=>!visible.has(id)).length;$('routine-job-selection').textContent=selectedRoutineJobs.size+' selected'+(hidden?' · '+hidden+' hidden':'');const master=$('routine-job-select-visible');master.checked=visible.size>0&&[...visible].every(id=>selectedRoutineJobs.has(id));master.indeterminate=!master.checked&&[...visible].some(id=>selectedRoutineJobs.has(id));master.disabled=routineJobBusy;$('routine-job-cancel-selected').disabled=routineJobBusy||![...selectedRoutineJobs.values()].some(r=>r.can_cancel);$('routine-job-clear-selected').disabled=routineJobBusy||!selectedRoutineJobs.size;}
$('routine-job-filters').addEventListener('submit',e=>{e.preventDefault();routineJobsView=$('routine-job-view').value;routineJobsSearch=$('routine-job-search').value.trim();routineJobsPage=1;rememberPortalNavigation();refresh();});
$('routine-job-view').addEventListener('change',e=>{routineJobsView=e.target.value;routineJobsPage=1;rememberPortalNavigation();refresh();});
$('routine-job-prev').addEventListener('click',()=>{if(routineJobsPage>1){routineJobsPage--;rememberPortalNavigation();refresh();}});$('routine-job-next').addEventListener('click',()=>{if(routineJobsPage<routineJobsPages){routineJobsPage++;rememberPortalNavigation();refresh();}});
$('routine-jobs-table').addEventListener('change',e=>{const id=e.target.dataset.routineJobSelect;if(!id)return;e.target.checked?selectedRoutineJobs.set(id,routineJobRows.find(r=>r.id===id)):selectedRoutineJobs.delete(id);updateRoutineJobSelection();});
$('routine-job-select-visible').addEventListener('change',e=>{for(const r of routineJobRows)e.target.checked?selectedRoutineJobs.set(r.id,r):selectedRoutineJobs.delete(r.id);renderRoutineJobs({runs:routineJobRows,page:routineJobsPage,pages:routineJobsPages,total:Number.parseInt($('routine-job-count').textContent)});});
$('routine-job-clear-selected').addEventListener('click',()=>{selectedRoutineJobs.clear();renderRoutineJobs({runs:routineJobRows,page:routineJobsPage,pages:routineJobsPages,total:Number.parseInt($('routine-job-count').textContent)});});
$('routine-job-cancel-selected').addEventListener('click',async()=>{if(routineJobBusy)return;const eligible=[...selectedRoutineJobs.values()].filter(r=>r.can_cancel);if(!eligible.length||!window.confirm('Cancel '+eligible.length+' selected jobs? Reports and erasure evidence will be retained.'))return;routineJobBusy=true;updateRoutineJobSelection();const failures=[];let done=0;try{for(const r of selectedRoutineJobs.values()){if(!r.can_cancel)continue;try{await api('/routine-runs/'+r.id+'/action',{method:'POST',body:JSON.stringify({action:'cancel',expected_step:r.step})});selectedRoutineJobs.delete(r.id);done++;}catch(e){failures.push(deviceLabel(r)+': '+e.message);}}await refresh();message(done+' routine jobs cancelled.'+(failures.length?' '+failures.join('; '):''),!!failures.length);}finally{routineJobBusy=false;updateRoutineJobSelection();}});
$('routine-new-erase').addEventListener('click',()=>{if(routineDirty){message('Save or discard the current draft first.',true);return;}$('routine-new').click();routineDraft.name='Erase and certify';routineDraft.steps=[newRoutineStep('boot'),newRoutineStep('erase'),newRoutineStep('finish')];routineSelectedStep=routineDraft.steps[1].id;$('routine-name').value=routineDraft.name;renderRoutineFlow();renderRoutineStep();routineEditorStatus();});
$('routine-step-settings').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)switchTab(b.dataset.tab);});
$('detail-close').addEventListener('click',()=>{routineRunId=null;});


function wipeRemaining(seconds){if(!Number.isFinite(seconds))return 'Time remaining unavailable';const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=seconds%60;return (h?h+'h ':'')+(m?m+'m ':'')+s+'s remaining';}
function eraseProgressHtml(r){return (r.erase_disks||[]).map(d=>{const active=d.stage==='erasing',p=Number.isFinite(d.percent)?d.percent:null,stale=active&&d.progress_stale;return '<div class="wipe-progress"><strong>'+esc(d.model||d.target)+'</strong><small>'+esc(d.target)+(d.size?' · '+bytes(d.size):'')+'</small>'+(active?'<progress max="100" '+(p===null?'':'value="'+p+'"')+' aria-label="Wipe progress for '+esc(d.target)+'"></progress><span>'+ (p===null?'Measuring progress':p+'%')+' · '+esc(stale?'Updates stopped · last estimate '+wipeRemaining(d.remaining_seconds):wipeRemaining(d.remaining_seconds))+'</span>':'<span>'+esc(d.stage==='complete'?'Verified erasure complete':stageName(d.stage))+'</span>')+'<small>'+esc(d.detail||'Waiting for ShredOS progress')+'</small>'+(stale?'<small class="error">Last update '+esc(dateText(d.progress_updated))+'. Inspect the PC.</small>':'')+'</div>';}).join('');}

async function refreshOpenRoutineProgress(){const id=routineRunId,generation=portalNavigationGeneration;if(!id||!$('details').open)return;try{const r=await api('/routine-runs/'+id);if(id===routineRunId&&generation===portalNavigationGeneration&&$('details').open&&$('routine-erase-progress'))$('routine-erase-progress').innerHTML=eraseProgressHtml(r);}catch{}}
setInterval(()=>{if(webSession&&!document.hidden)refreshOpenRoutineProgress();},5000);

async function removeRoutineJob(id){const r=await api('/routine-runs/'+id);if(!r.can_remove)throw new Error('This job cannot be removed while its operation is active.');const stopped=!!r.can_confirm_stopped;const question=stopped?'Confirm you have stopped the software wipe on '+deviceLabel(r)+' and it is no longer writing to any drive. Remove its job from the portal? The erasure will be recorded as incomplete and unverified. Reports will be retained.':'Remove job for '+deviceLabel(r)+' from the portal? Reports and erasure evidence will remain in Reports.';if(!window.confirm(question))return;const current=(r.erase_disks||[]).find(d=>d.id===r.workflow_id);await api('/routine-runs/'+r.id+'/action',{method:'POST',body:JSON.stringify({action:'remove',expected_step:r.step,stopped_locally:stopped,expected_progress_updated:current?.progress_updated||null})});selectedRoutineJobs.delete(id);closePortalDialogs();routineRunId=null;rememberPortalNavigation();await refresh();message('Job removed. Reports and erasure evidence retained.');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-routine-remove-job]');if(!b)return;try{await removeRoutineJob(b.dataset.routineRemoveJob);}catch(error){message(error.message,true);}});
